INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66219731', 66219731, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BALAI TEKNIK PERKERETAAPIAN SURABAYA', 'PEMBONGKARAN EKS TOWER RU6  DI STASIUN KEDIRI YANG SUDAH TIDAK TERPAKAI OLEH PT. KERETA API INDONESIA (PERSERO) DAOP 7 MADIUN', 'Pekerjaan Konstruksi', 'Pengadaan Langsung', 'Jawa Timur, Kediri (Kab.)', 75000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 paket', 'Dalam rangka menjaga keselamatan operasional perjalanan kereta api serta meningkatkan pengamanan aset prasarana perkeretaapian, Direktorat Jenderal Perkeretaapian melalui Balai Teknik Perkeretaapian Kelas I Surabaya melakukan identifikasi terhadap bangunan dan infrastruktur yang sudah tidak difungsikan di wilayah kerja Daerah Operasi 7 Madiun. Salah satu temuan adalah keberadaan Eks Tower RU6 di Stasiun Kediri yang saat ini sudah tidak digunakan dalam sistem telekomunikasi maupun operasional perkeretaapian. Berdasarkan hasil koordinasi dengan PT Kereta Api Indonesia (Persero) Daop 7 Madiun, tower dimaksud tidak lagi dimanfaatkan dan tidak berada dalam program perawatan rutin. Kondisi tersebut berpotensi menimbulkan risiko keselamatan, mengingat struktur menara memiliki ketinggian ±58 meter dan berada dalam area prasarana yang berdekatan dengan jalur operasional kereta api. Seiring waktu, faktor usia, paparan cuaca, serta kemungkinan degradasi material dapat meningkatkan risiko ketidakstabilan struktur. Keberadaan tower nonaktif ini juga berdampak pada penataan ruang milik jalur (Right of Way), menghambat optimalisasi pemanfaatan lahan prasarana, serta berpotensi mengganggu kegiatan pemeliharaan dan pengembangan sistem perkeretaapian di masa mendatang. Oleh karena itu, diperlukan tindakan pembongkaran secara terencana, aman, dan terkendali guna menghilangkan potensi bahaya serta mensterilkan area prasarana dari infrastruktur yang tidak memiliki fungsi operasional. Kegiatan pembongkaran Eks Tower RU6 ini merupakan bagian dari program pengamanan dan penertiban aset prasarana perkeretaapian, sebagai bentuk komitmen Direktorat Jenderal Perkeretaapian dalam mewujudkan sistem transportasi kereta api yang selamat, aman, andal, dan berkelanjutan.', 'Ruang Lingkup kegiatan Pembongkaran Eks Tower RU6 Tidak Terpakai di Stasiun Kediri meliputi: a. Pekerjaan persiapan, termasuk survei lapangan, pengukuran kondisi eksisting, penyusunan rencana metode kerja (method statement), serta koordinasi dengan PT Kereta Api Indonesia (Persero) Daop 7 Madiun terkait pengamanan operasional perjalanan kereta api. b. Pengamanan lokasi pekerjaan, pemasangan rambu dan sistem peringatan kerja, serta penataan area kerja agar tidak mengganggu operasional perkeretaapian. c. Pelepasan dan pembersihan seluruh aksesori, perangkat, kabel, dan komponen lain yang melekat pada struktur tower. d. Pembongkaran struktur utama tower setinggi ±58 meter secara bertahap dan terkendali sesuai metode teknis yang disetujui. e. Penurunan, pengumpulan, dan penataan material hasil pembongkaran di lokasi yang telah ditentukan. f. Pengangkutan material hasil pembongkaran ke gudang atau lokasi penyimpanan yang ditetapkan oleh Direktorat Jenderal Perkeretaapian. g. Pembersihan akhir area pekerjaan hingga dinyatakan bersih, aman, dan siap dimanfaatkan kembali.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2624019);
