INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66221332', 66221332, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Perangkat Multimedia', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lok', 'Perangkat Multimedia (seperti sistem video conference, perangkat display, dan sistem audio) merupakan komponen penting untuk menunjang kegiatan rapat, command center, dan diseminasi informasi baik internal maupun eksternal. Perangkat ini menuntut keandalan operasional. Komponen dalam sistem multimedia meliputi perangkat display, perangkat audio, perangkat video conference, dan perangkat lunak pendukung. Perangkat ini tersebar di berbagai ruang strategis di Kantor Pusat BMKG, Jakarta. Mengingat peranannya yang sangat penting, diperlukan upaya pemeliharaan (maintenance) secara berkala dan profesional untuk menjaga kontinuitas operasionalnya, mencegah terjadinya kegagalan sistem (failure), dan memastikan performa sistem tetap optimal. Kegiatan pemeliharaan ini mencakup dukungan teknis, pemeliharaan perangkat keras dan perangkat lunak, serta pembaruan keamanan yang diperlukan.', 'Menjamin kontinuitas operasional dan ketersediaan tinggi (High Availability) fungsi perangkat multimedia dalam mendukung rapat, konferensi, dan diseminasi informasi BMKG. Melakukan pemeliharaan preventif untuk mencegah potensi kegagalan perangkat keras dan perangkat lunak multimedia. Melakukan pemeliharaan korektif (troubleshooting) dengan waktu respon (response time) yang cepat jika terjadi gangguan. Memastikan perangkat lunak pendukung (sistem operasi, driver, dan aplikasi konferensi) selalu terbarui (up-to-date) dengan patch keamanan terbaru. Menjaga performa sistem audio dan visual agar tetap optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2624730);
