INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66219093', 66219093, 'analyze_legacy', 'Badan Pusat Statistik', 'central', 'BADAN PUSAT STATISTIK KAB KUTAI BARAT', 'Alat Rumah Tangga (ARK)', 'Barang', 'Pengadaan Langsung', 'Kalimantan Timur, Kutai Barat (Kab.)', 5000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1 - THN, @Rp 5.000.000 )', 'Alat Rumah Tangga (ARK) ( 1 - THN, @Rp 5.000.000 )', 'Nama Paket : Pengadaan Alat Rumah Tangga (ARK) Volume : 1 THN (Tahun) Harga Satuan : @ Rp5.000.000 1. Ruang Lingkup Pekerjaan Penyedia melaksanakan pengadaan alat rumah tangga untuk mendukung kegiatan operasional dan kebersihan di lingkungan kantor selama periode 1 (satu) tahun. 2. Spesifikasi Teknis 1. Alat rumah tangga yang disediakan dapat meliputi: o Sapu lantai dan pengki o Pel lantai dan ember o Lap pembersih o Tempat sampah o Cairan pembersih lantai/kaca o Perlengkapan kebersihan lainnya sesuai kebutuhan kantor 2. Barang yang disediakan merupakan barang baru, layak pakai, dan sesuai standar perlengkapan kebersihan perkantoran. 3. Jenis dan jumlah barang dapat disesuaikan dengan kebutuhan operasional selama periode kegiatan. 3. Persyaratan 1. Harga yang ditawarkan merupakan harga wajar dan sesuai harga pasar yang berlaku. 2. Harga sudah termasuk pajak, biaya pengemasan, dan pengiriman. 3. Penyedia bertanggung jawab atas kualitas dan kelengkapan barang yang diserahkan. 4. Apabila terdapat barang yang rusak atau tidak sesuai spesifikasi, penyedia wajib melakukan penggantian tanpa biaya tambahan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2627619);
